import math

def check_condition(n):
    if n < 2:
        return False

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            k_squared_minus_1 = k**2 - 1
            if k_squared_minus_1 % n != 0:
                return False, k, k_squared_minus_1
    return True, None, None

test_values = [2, 3, 4, 5, 6, 7, 8, 9, 10, 12]
results = {}

for n in test_values:
    passes, k_fail, val_fail = check_condition(n)
    results[n] = {
        "Passes": passes,
        "k_fail": k_fail,
        "val_fail": val_fail
    }

print("--- Test Results ---")
for n, res in results.items():
    if res["Passes"]:
        print(f"n={n}: PASSES. All k coprime to n satisfy k^2 - 1 = 0 mod n.")
    else:
        print(f"n={n}: FAILS. Counterexample found: k={res['k_fail']}, k^2 - 1 = {res['val_fail']} (not divisible by {n}).")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_condition(n):
    if n < 2:
        return False
    for k in range(1, n):
        if gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k * k - 1) % n != 0:
                return False
    return True

# Test known solutions
test_numbers = [2, 3, 4, 6, 8, 12, 24, 10, 15]
print("Checking small cases:")
for n in test_numbers:
    result = check_condition(n)
    print(f"n={n}: Works? {result}")

# Test a larger number potentially missed by simple checking, e.g., 30
print("\nChecking n=30:")
result_30 = check_condition(30)
print(f"n=30: Works? {result_30}")
